const recordIspinsWeeklyClear = `-- name: RecordIspinsWeeklyClear :exec
INSERT INTO character_events(character_id,event_key,config_version,model,outcome)
VALUES(?1,?2,?3,?4,
CAST(json_object('week',CAST(?5 AS TEXT),'run',CAST(?6 AS TEXT)) AS BLOB))
`

type RecordIspinsWeeklyClearParams struct {
	CharacterID   int64
	EventKey      string
	ConfigVersion string
	Model         string
	Week          string
	Run           string
}

// json_object returns TEXT; character_events.outcome is a BLOB column with BLOB
// affinity, which stores TEXT unchanged, so the JSON is cast to BLOB to keep the
// byte round-trip database/sql needs for a json.RawMessage scan target (D24).
func (q *Queries) RecordIspinsWeeklyClear(ctx context.Context, arg RecordIspinsWeeklyClearParams) error {
	_, err := q.db.ExecContext(ctx, recordIspinsWeeklyClear,
		arg.CharacterID,
		arg.EventKey,
		arg.ConfigVersion,
		arg.Model,
		arg.Week,
		arg.Run,
	)
	return err
}

const reserveTowerEntry = `-- name: ReserveTowerEntry :one
UPDATE account_tower_progress SET entry_day=CAST(?1 AS TEXT),
entries_today=CASE WHEN entry_day=CAST(?1 AS TEXT) THEN entries_today+1 ELSE 1 END
WHERE account_id=?2 AND tower_key=?3 AND highest_cleared+1=?4
RETURNING highest_cleared,CAST(entry_day AS TEXT) AS entry_day,entries_today,last_run_id
`

type ReserveTowerEntryParams struct {
	Day       string
	AccountID int64
	TowerKey  string
	Floor     int16
}

type ReserveTowerEntryRow struct {
	HighestCleared int16
	EntryDay       string
	EntriesToday   int16
	LastRunID      string
}

// entry_day is assigned in this same statement, so the returned
// CAST(entry_day AS TEXT) is non-NULL and keeps the plain `string` shape
// PostgreSQL returns from entry_day::text.
func (q *Queries) ReserveTowerEntry(ctx context.Context, arg ReserveTowerEntryParams) (ReserveTowerEntryRow, error) {
	row := q.db.QueryRowContext(ctx, reserveTowerEntry,
		arg.Day,
		arg.AccountID,
		arg.TowerKey,
		arg.Floor,
	)
	var i ReserveTowerEntryRow
	err := row.Scan(
		&i.HighestCleared,
		&i.EntryDay,
		&i.EntriesToday,
		&i.LastRunID,
	)
	return i, err
}

const runFatigueLedger = `-- name: RunFatigueLedger :one
SELECT CAST(COALESCE(SUM(f.cost),0) AS INTEGER) AS charged,CAST(COUNT(*) AS INTEGER) AS rooms
FROM character_fatigue_rooms f JOIN characters c ON c.id=f.character_id
WHERE c.account_id=?1 AND c.id=?2 AND f.run_id=?3
`

type RunFatigueLedgerParams struct {
	AccountID   int64
	CharacterID int64
	RunID       string
}

type RunFatigueLedgerRow struct {
	Charged int64
	Rooms   int64
}

func (q *Queries) RunFatigueLedger(ctx context.Context, arg RunFatigueLedgerParams) (RunFatigueLedgerRow, error) {
	row := q.db.QueryRowContext(ctx, runFatigueLedger, arg.AccountID, arg.CharacterID, arg.RunID)
	var i RunFatigueLedgerRow
	err := row.Scan(&i.Charged, &i.Rooms)
	return i, err
}

