const saveWorld = `-- name: SaveWorld :execrows
UPDATE character_world SET position=?1,revision=revision+1,
updated_at=(CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER))
WHERE EXISTS(SELECT 1 FROM characters c WHERE c.id=character_world.character_id AND c.account_id=?2)
AND character_id=?3 AND revision=?4
`

type SaveWorldParams struct {
	Position    json.RawMessage
	AccountID   int64
	CharacterID int64
	Revision    int64
}

func (q *Queries) SaveWorld(ctx context.Context, arg SaveWorldParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, saveWorld,
		arg.Position,
		arg.AccountID,
		arg.CharacterID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

